        // we need to know how may bytes were read to write them to the
        // byteBuffer
        int len;
        while ((len = inputStream.read(buffer)) != -1) {
            byteBuffer.write(buffer, 0, len);
        }

        // and then we can return your byte array.
        return byteBuffer.toByteArray();
    } finally {
        if (inputStream != null) {
            inputStream.close();
